                            real.release(i)
                    else:
                        self.assertEqual(real.release(i), want)
                elif op == "expire":
                    ttl = rng.randint(0, 4)
                    self.assertEqual(real.expire(day, ttl), model.expire(day, ttl))
                else:
                    self.assertEqual(real.free_counts(), model.counts())


