def oracle(members, ballots, proxies, pct, chair):
    mem = set(members)
    votes = {m: v for m, v in ballots.items() if m in mem}
    considered, used = [], set()
    for g, h in proxies:
        if g in mem and h in mem and g not in used:
            used.add(g)
            considered.append((g, h))
